                        "shared_space_album_hidden"."spaceId" = "shared_space_album"."spaceId"
                        and "shared_space_album_hidden"."albumId" = "shared_space_album"."albumId"
                        and "shared_space_album_hidden"."userId" = $12::uuid
                    )
                )
              )
            )
          )
        )
        and exists (
          select
          from
            "tag_closure"
            inner join "tag_asset" on "tag_asset"."tagId" = "tag_closure"."id_descendant"
          where
            "tag_asset"."assetId" = "asset"."id"
            and "tag_closure"."id_ancestor" = any ($13::uuid[])
        )
        and f_unaccent (ocr_search.text) %>> f_unaccent ($14)
        and exists (
          select
          from
            "asset_exif"
          where
            "asset_exif"."assetId" = "asset"."id"
            and (
              "asset_exif"."city" = $15
              and "asset_exif"."rating" >= $16
            )
        )
    )
  ),
  identity_faces AS (
    SELECT
      pairs."identityId",
      count(*)::int AS "assetCount"
    FROM
      (
        SELECT DISTINCT
          face_identity_face."identityId",
          asset_face."assetId"
        FROM
          face_identity_face
          INNER JOIN asset_face ON asset_face.id = face_identity_face."assetFaceId"
          INNER JOIN filtered_assets ON filtered_assets.id = asset_face."assetId"
        WHERE
          asset_face."deletedAt" IS NULL
          AND asset_face."isVisible" = true
      ) AS pairs
    GROUP BY
      pairs."identityId"
  ),
  profiles AS (
    SELECT
      'user-person'::text AS "profileType",
      person."personGroupId" AS "profileId",
      NULL::uuid AS "spaceId",
      (
        SELECT
          "person_identity"."identityId"
        FROM
          "person_identity"
        WHERE
          "person_identity"."personGroupId" = "person"."personGroupId"
      ) AS "identityId",
      person.name,
      person."isHidden",
      person."updatedAt",
      0 AS "profileRank"
    FROM
      person
    WHERE
      person."ownerId" = $17
      AND (
        SELECT
          "person_identity"."identityId"
        FROM
          "person_identity"
        WHERE
          "person_identity"."personGroupId" = "person"."personGroupId"
      ) IS NOT NULL
      AND EXISTS (
        SELECT
          1
        FROM
          identity_faces
        WHERE
          identity_faces."identityId" = (
            SELECT
              "person_identity"."identityId"
            FROM
              "person_identity"
            WHERE
              "person_identity"."personGroupId" = "person"."personGroupId"
          )
      )
    UNION ALL
    SELECT
      'space-person'::text AS "profileType",
      shared_space_person.id AS "profileId",
      shared_space_person."spaceId",
      shared_space_person."identityId",
      COALESCE(
        NULLIF(shared_space_person_alias.alias, ''),
        shared_space_person.name,
        ''
      ) AS name,
      shared_space_person."isHidden",
      shared_space_person."updatedAt",
      CASE
        WHEN NULLIF(shared_space_person_alias.alias, '') IS NULL THEN 2
        ELSE 1
      END AS "profileRank"
    FROM
      shared_space_person
      LEFT JOIN shared_space_person_alias ON shared_space_person_alias."personId" = shared_space_person.id
      AND shared_space_person_alias."userId" = $18
    WHERE
      shared_space_person."spaceId" = any ($19::uuid[])
      AND shared_space_person."identityId" IS NOT NULL
      AND EXISTS (
        SELECT
          1
        FROM
          shared_space_person_face
          INNER JOIN asset_face AS profile_face ON profile_face.id = shared_space_person_face."assetFaceId"
        WHERE
          shared_space_person_face."personId" = shared_space_person.id
          AND profile_face."deletedAt" IS NULL
          AND profile_face."isVisible" = true
      )
      AND EXISTS (
        SELECT
          1
        FROM
          identity_faces
        WHERE
          identity_faces."identityId" = shared_space_person."identityId"
      )
  ),
  ranked_profiles AS (
    SELECT
      profiles.*,
      row_number() OVER (
        PARTITION BY
          profiles."identityId"
        ORDER BY
          NULLIF(profiles.name, '') IS NULL,
          profiles."profileRank",
          lower(profiles.name),
          profiles."updatedAt" DESC,
          profiles."profileId"
      ) AS display_rn,
      row_number() OVER (
        PARTITION BY
          profiles."identityId"
        ORDER BY
          CASE
            WHEN profiles."profileType" = 'user-person' THEN 0
            ELSE profiles."profileRank"
          END,
          NULLIF(profiles.name, '') IS NULL,
          lower(profiles.name),
          profiles."updatedAt" DESC,
          profiles."profileId"
      ) AS primary_rn
    FROM
      profiles
    WHERE
      profiles."isHidden" = false
  )
SELECT
  CASE
    WHEN primary_profiles."profileType" = 'space-person' THEN 'space-person:' || primary_profiles."profileId"::text
    ELSE 'person:' || primary_profiles."profileId"::text
  END AS id,
  COALESCE(
    NULLIF(display_profiles.name, ''),
    primary_profiles.name,
    ''
  ) AS name,
  primary_profiles."profileType",
  primary_profiles."profileId",
  primary_profiles."spaceId",
  primary_profiles."identityId",
  counted."assetCount" AS count
FROM
  ranked_profiles AS primary_profiles
  INNER JOIN ranked_profiles AS display_profiles ON display_profiles."identityId" = primary_profiles."identityId"
  AND display_profiles.display_rn = 1
  LEFT JOIN identity_faces AS counted ON counted."identityId" = primary_profiles."identityId"
WHERE
  primary_profiles.primary_rn = 1
ORDER BY
  NULLIF(
    COALESCE(
      NULLIF(display_profiles.name, ''),
      primary_profiles.name,
      ''
    ),
    ''
  ) IS NULL,
  lower(
    COALESCE(
      NULLIF(display_profiles.name, ''),
      primary_profiles.name,
      ''
    )
  ),
  primary_profiles."profileId"
commit

